<?php require __DIR__.'/../app/bootstrap.php'; security_headers();$e='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf('login',$_POST['_csrf']??null))$e='Solicitação inválida.';elseif(admin_login($_POST['email']??'',$_POST['password']??'')){header('Location: /admin/',true,303);exit;}else $e='Email ou senha inválidos.';}?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/admin/admin.css"><title>Entrar na administração</title></head><body class="admin-page"><main class="admin-login"><p class="admin-kicker">Direct Positive Workshop</p><h1 class="admin-title">Administração</h1><?php if($e):?><p class="admin-error" role="alert"><?=h($e)?></p><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('login'))?>"><label class="admin-field">Email<input name="email" type="email" autocomplete="email" required></label><label class="admin-field">Senha<input name="password" type="password" autocomplete="current-password" required></label><button class="admin-button">Entrar</button></form></main></body></html>
